var GEO_SUONI=(function(){
  var A={ctx:null,out:null,buf:{},car:false};
  var NOMI=["pin","conferma","tasto","volo","soldi","sposta"];
  function muto(){
    try{if(window.TWS&&window.TWS.on===false)return true;}catch(e){}
    try{if(localStorage.getItem("geo_suoni")==="0")return true;}catch(e){}
    return false;
  }
  function prepara(){
    if(muto())return;
    try{
      if(!A.ctx){var C=window.AudioContext||window.webkitAudioContext;if(!C)return;A.ctx=new C();A.out=A.ctx.createGain();A.out.gain.value=0.7;A.out.connect(A.ctx.destination);}
      if(A.ctx.state==="suspended")A.ctx.resume();
    }catch(e){return;}
    if(A.car)return;A.car=true;
    NOMI.forEach(function(n){
      fetch("geo_asset/suoni/"+n+".mp3").then(function(r){return r.ok?r.arrayBuffer():null;}).then(function(b){
        if(!b)return;
        return new Promise(function(ok,ko){A.ctx.decodeAudioData(b,ok,ko);}).then(function(x){A.buf[n]=x;});
      }).catch(function(){});
    });
  }
  function suona(n,o){
    if(muto()||document.hidden)return;
    prepara();
    if(!A.ctx||!A.buf[n])return;
    o=o||{};
    try{
      var s=A.ctx.createBufferSource();s.buffer=A.buf[n];if(o.rate)s.playbackRate.value=o.rate;
      var g=A.ctx.createGain();g.gain.value=o.vol==null?1:o.vol;s.connect(g);g.connect(A.out);
      s.start(A.ctx.currentTime+(o.dopo||0)/1000);
    }catch(e){}
  }
  return {prepara:prepara,suona:suona};
})();
